// One-off 2026-10-20: PDF Editor monorepo keys tagged 201026 (E15, PDFHELP-2581): descriptions + 11 target langs, unverified.
// Writes only empty descriptions and empty targets, only if EN is unchanged. EN never written.
// MODE is set in the 'Build writes' node.
const LANGS = ['de','es','fr','it','ko','ms','nl','pt','sv','th','vi'];
const INFO = `E15 – application for restitution naturalisation under section 15 of the German Nationality Act (Einbürgerung nach § 15 StAG), handled by the Bundesverwaltungsamt (German Federal Office of Administration). "E15" is the official form code. German forms, PDFHELP-2581.`;
const PAGE = `For the E15 landing page (/e15-form). ` + INFO;
function same(s) { const o = {}; for (const l of LANGS) { o[l] = s; } return o; }
const K = {
'959995879': { en: `E15`, d: `Footer quick links, "Forms" column: link to the E15 form page (/e15-form). ` + INFO, t: same(`E15`) },
'959995880': { en: `E15`, d: `Logged-in dashboard, "Forms" list: name of the form. ` + INFO, t: same(`E15`) },
'959995888': { en: `E15`, d: `Main navigation, "Forms" menu (desktop dropdown and mobile menu): link to the E15 form page (/e15-form). ` + INFO, t: same(`E15`) },
'959995883': { en: `E15`, d: `Form name on the E15 landing page (/e15-form), inserted as the form name in the page strings, e.g. the hero title "Get 2026 E15 Form". ` + INFO, t: same(`E15`) },
'959995882': { en: `[%1$s:type]`, d: `Card label for the E15 form in the "Other forms" grid on form landing pages. The source is only the form-name placeholder – keep the placeholder as is, no text to add. ` + INFO, t: same(`[%1$s:type]`) },
'959995881': { en: `This website is not affiliated with any German government authority`, d: `Disclaimer line shown under the hero on the E15 page (/e15-form). Refers to German government authorities in general (federal, state or local), not one specific agency. German forms, PDFHELP-2581.`, t: {
  de: `Diese Webseite ist mit keiner deutschen Behörde verbunden`,
  es: `Esta página web no está afiliada a ningún organismo público alemán`,
  fr: `Ce site web n'est affilié à aucune autorité publique allemande`,
  it: `Questo sito web non è affiliato ad alcuna autorità pubblica tedesca`,
  ko: `본 웹 사이트는 독일 정부 기관과 관련이 없습니다.`,
  ms: `Laman web ini tidak mempunyai kaitan dengan mana-mana pihak berkuasa kerajaan Jerman`,
  nl: `Deze website is niet verbonden met een Duitse overheidsinstantie`,
  pt: `Este site não tem vínculo com nenhum órgão do governo alemão`,
  sv: `Denna webbplats är inte ansluten till någon tysk myndighet`,
  th: `เว็บไซต์นี้ไม่มีความเกี่ยวข้องกับหน่วยงานรัฐบาลเยอรมันใด ๆ`,
  vi: `Trang mạng này không liên kết với bất kỳ cơ quan chính phủ Đức nào` } },
'959995884': { en: `Fill in the German E15 application for restitution naturalisation under section 15 of the Nationality Act. For people aged 16 or over living abroad. Download a PDF.`, d: `SEO meta description (search results snippet). Recommended max ~160 characters. Not visible on the page. ` + PAGE, t: {
  de: `Fülle den deutschen Antrag E15 auf Wiedergutmachungseinbürgerung nach § 15 des Staatsangehörigkeitsgesetzes aus. Für Personen ab 16 Jahren mit Wohnsitz im Ausland. Lade ein PDF herunter.`,
  es: `Rellena la solicitud alemana E15 de naturalización por restitución según el artículo 15 de la Ley de Nacionalidad. Para personas de 16 años o más que viven en el extranjero. Descarga un PDF.`,
  fr: `Remplissez la demande allemande E15 de naturalisation à titre de réparation (article 15 de la loi sur la nationalité). Pour les personnes de 16 ans ou plus vivant à l'étranger. Téléchargez un PDF.`,
  it: `Compila la domanda tedesca E15 di naturalizzazione riparatoria ai sensi del paragrafo 15 della legge sulla cittadinanza. Per le persone di almeno 16 anni residenti all'estero. Scarica un PDF.`,
  ko: `독일 국적법 제15조에 따른 E15 원상회복 귀화 신청서를 작성하세요. 해외에 거주하는 만 16세 이상인 분이 대상입니다. PDF를 다운로드하세요.`,
  ms: `Isi permohonan E15 Jerman untuk naturalisasi pemulihan di bawah seksyen 15 Akta Kewarganegaraan. Untuk individu berumur 16 tahun ke atas yang tinggal di luar negara. Muat turun PDF.`,
  nl: `Vul de Duitse E15-aanvraag voor herstelnaturalisatie op grond van artikel 15 van de nationaliteitswet in. Voor personen van 16 jaar of ouder die in het buitenland wonen. Download een pdf.`,
  pt: `Preencha o requerimento alemão E15 de naturalização por reparação, conforme o artigo 15 da Lei da Nacionalidade. Para pessoas com 16 anos ou mais que moram no exterior. Baixe um PDF.`,
  sv: `Fyll i den tyska E15-ansökan om naturalisation som gottgörelse enligt paragraf 15 i medborgarskapslagen. För personer som är 16 år eller äldre och bor utomlands. Ladda ner en PDF.`,
  th: `กรอกคำร้อง E15 ของเยอรมนีเพื่อขอแปลงสัญชาติเพื่อการชดเชยตามมาตรา 15 ของกฎหมายสัญชาติ สำหรับผู้ที่มีอายุ 16 ปีขึ้นไปและอาศัยอยู่ในต่างประเทศ ดาวน์โหลด PDF`,
  vi: `Điền đơn E15 của Đức xin nhập tịch phục hồi theo Điều 15 Luật Quốc tịch. Dành cho người từ 16 tuổi trở lên sống ở nước ngoài. Tải xuống tệp PDF.` } },
'959995885': { en: `Complete the Bundesverwaltungsamt E15 naturalisation application in PDF Help and download a PDF.`, d: `Social sharing (Open Graph) description, shown when the page link is shared. Not visible on the page. ` + PAGE, t: {
  de: `Fülle mit PDF Help den Einbürgerungsantrag E15 des Bundesverwaltungsamts aus und lade ein PDF herunter.`,
  es: `Completa la solicitud de naturalización E15 del Bundesverwaltungsamt en PDF Help y descarga un PDF.`,
  fr: `Remplissez la demande de naturalisation E15 du Bundesverwaltungsamt avec PDF Help et téléchargez un PDF.`,
  it: `Compila la domanda di naturalizzazione E15 del Bundesverwaltungsamt con PDF Help e scarica un PDF.`,
  ko: `PDF Help에서 독일 연방행정청(Bundesverwaltungsamt) E15 귀화 신청서를 작성하고 PDF를 다운로드하세요.`,
  ms: `Lengkapkan permohonan naturalisasi E15 Bundesverwaltungsamt dalam PDF Help dan muat turun PDF.`,
  nl: `Vul de E15-naturalisatieaanvraag van het Bundesverwaltungsamt in met PDF Help en download een pdf.`,
  pt: `Preencha o requerimento de naturalização E15 do Bundesverwaltungsamt no PDF Help e baixe um PDF.`,
  sv: `Fyll i Bundesverwaltungsamts E15-ansökan om naturalisation med PDF Help och ladda ner en PDF.`,
  th: `กรอกคำร้องขอแปลงสัญชาติ E15 ของ Bundesverwaltungsamt ใน PDF Help แล้วดาวน์โหลด PDF`,
  vi: `Điền đơn xin nhập tịch E15 của Bundesverwaltungsamt trong PDF Help và tải xuống tệp PDF.` } },
'959995886': { en: `Fill In an E15 Form Online - PDF Help`, d: `Social sharing (Open Graph) title, shown when the page link is shared. Not visible on the page. ` + PAGE, t: {
  de: `E15 online ausfüllen – PDF Help`, es: `Rellena un E15 en línea - PDF Help`, fr: `Remplissez un formulaire E15 en ligne - PDF Help`, it: `Compila un E15 online - PDF Help`, ko: `온라인으로 E15 작성 - PDF Help`, ms: `Isi borang E15 dalam talian - PDF Help`, nl: `E15 online invullen - PDF Help`, pt: `Preencha um E15 online – PDF Help`, sv: `Fyll i en E15 online - PDF Help`, th: `กรอกแบบฟอร์ม E15 ออนไลน์ - PDF Help`, vi: `Điền mẫu E15 trực tuyến - PDF Help` } },
'959995887': { en: `Fill In an E15 Form Online | Naturalisation Application | PDF Help`, d: `SEO page title (browser tab and search results). Recommended max ~60 characters. Not visible on the page. ` + PAGE, t: {
  de: `E15-Formular online ausfüllen | Einbürgerungsantrag | PDF Help`, es: `Rellena el formulario E15 en línea | Solicitud de naturalización | PDF Help`, fr: `Remplissez le formulaire E15 en ligne | Demande de naturalisation | PDF Help`, it: `Compila il modulo E15 online | Domanda di naturalizzazione | PDF Help`, ko: `온라인으로 E15 양식 작성 | 귀화 신청서 | PDF Help`, ms: `Isi borang E15 dalam talian | Permohonan naturalisasi | PDF Help`, nl: `E15-formulier online invullen | Naturalisatieaanvraag | PDF Help`, pt: `Preencha o formulário E15 online | Requerimento de naturalização | PDF Help`, sv: `Fyll i E15-formulär online | Ansökan om naturalisation | PDF Help`, th: `กรอกแบบฟอร์ม E15 ออนไลน์ | คำร้องขอแปลงสัญชาติ | PDF Help`, vi: `Điền mẫu E15 trực tuyến | Đơn xin nhập tịch | PDF Help` } }
};
for (const id in K) { for (const l of LANGS) { if (typeof K[id].t[l] !== 'string' || !K[id].t[l].trim()) { throw new Error('missing ' + id + ' ' + l); } } }
if (Object.keys(K).length !== 10) { throw new Error('expected 10 keys'); }
return [{ json: { langs: LANGS, ids: Object.keys(K).join(','), K: K } }];

const MODE = 'all'; // 'check' | 'test' | 'all'
const cfg = $('Config').first().json;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { throw new Error('Guard fetch failed: ' + JSON.stringify(b).slice(0, 300)); }
const items = []; const skip = [];
for (const k of b.keys) {
  const spec = cfg.K[String(k.key_id)]; if (!spec) { continue; }
  if (k.is_archived || k.is_plural) { skip.push([k.key_id, 'archived/plural']); continue; }
  const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = typeof t.translation === 'string' ? t.translation : JSON.stringify(t.translation); }
  if ((m.en || '') !== spec.en) { skip.push([k.key_id, 'EN changed']); continue; }
  const it = { key_id: k.key_id };
  if (String(k.description || '').trim()) { skip.push([k.key_id, 'description already set']); } else { it.description = spec.d; }
  const tr = [];
  for (const iso of cfg.langs) {
    if (String(m[iso] || '').trim()) { skip.push([k.key_id, iso, 'already filled']); continue; }
    tr.push({ language_iso: iso, translation: spec.t[iso], is_unverified: true });
  }
  if (tr.length) { it.translations = tr; }
  if (it.description || it.translations) { items.push(it); }
}
const found = b.keys.filter(function (k) { return cfg.K[String(k.key_id)]; }).length;
let sel = items;
if (MODE === 'test') { sel = items.filter(function (x) { return String(x.key_id) === '959995888'; }).map(function (x) { const o = { key_id: x.key_id, translations: (x.translations || []).filter(function (t) { return t.language_iso === 'de'; }) }; if (x.description) { o.description = x.description; } return o; }); }
const n = sel.reduce(function (a, x) { return a + (x.translations || []).length; }, 0);
const nd = sel.filter(function (x) { return x.description; }).length;
return [{ json: { mode: MODE, keys_expected: Object.keys(cfg.K).length, keys_found: found, translations_to_write: n, descriptions_to_write: nd, skipped: skip, body: JSON.stringify({ keys: sel }) } }];

const cfg = $('Config').first().json;
const mode = $('Build writes').first().json.mode;
const b = $input.first().json.body || {};
if (!Array.isArray(b.keys)) { return [{ json: { error: 'read-back failed' } }]; }
let match = 0, empty = 0, dmatch = 0, dother = 0; const diff = [];
for (const k of b.keys) {
  const spec = cfg.K[String(k.key_id)]; if (!spec) { continue; }
  if (k.description === spec.d) { dmatch++; } else if (String(k.description || '').trim()) { dother++; diff.push([k.key_id, 'description', String(k.description).slice(0, 80)]); }
  const m = {}; for (const t of (k.translations || [])) { m[t.language_iso] = t; }
  for (const iso of cfg.langs) { const v = (m[iso] || {}).translation; if (v === spec.t[iso]) { match++; } else if (!String(v || '').trim()) { empty++; } else { diff.push([k.key_id, iso, String(v).slice(0, 100)]); } }
  if ((m.en || {}).translation !== spec.en) { diff.push([k.key_id, 'en', 'EN differs']); }
}
let w = [];
try { w = $('WRITE').all().map(function (x) { return { status: x.json.statusCode, written: ((x.json.body || {}).keys || []).length, errors: (x.json.body || {}).errors || (x.json.body || {}).error || null }; }); } catch (e) { w = 'not run'; }
return [{ json: { mode: mode, write: w, readback: { translations_match: match, still_empty: empty, different: diff, descriptions_match: dmatch, descriptions_other: dother } } }];
